//     for i in range(2):  # tpyc: ok
//         if i == 0:
//             p = Flat(i)
//         else:
//             p = Flat(i + 20)
//     p.n += 1
//     self.v = p.n
inline Built::Built() {
    std::optional<Flat> __slot_1;
    std::optional<Flat> __slot_2;
    Flat* p;
    for (int32_t i = 0; i < 2; ++i) {
        if ((i == 0)) {
            p = &*(__slot_1 = Flat(i));
        } else {
            p = &*(__slot_2 = Flat((::tpy::add_check<int32_t>(i, 20))));
        }
    }
    p->n = ::tpy::add_check<int32_t>(p->n, 1);
    this->v = p->n;
}

// # Method position, sibling loop.
// def run(self) -> None:
//     for i in range(2):
//         f = Flat(i)  # tpyc: ok
//     for k in range(2):
//         print("sib_method", k)
//     f.n += 100
//     print("sib_method", f.n)
inline void SibHolder::run() const {
    std::optional<Flat> f;
    for (int32_t i = 0; i < 2; ++i) {
        f = Flat(i);
    }
    for (int32_t k = 0; k < 2; ++k) {
        std::cout << "sib_method" << " " << k << "\n";
    }
    f->n = ::tpy::add_check<int32_t>(f->n, 100);
    std::cout << "sib_method" << " " << f->n << "\n";
}

